from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts.pages.panels.view import ViewPanel
from taf.selenium.sbts.pages.configuration.configuration_management import ConfigurationCommonAction
from taf.selenium.sbts.pages.navigatable_page import NavigatablePage


class DefinitionErrorsPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Definition Errors will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'Configuration Management', 'Parameter Editor']
    _DEFINITION_ERRORS_XPATH = "//a[.//span[text()='Definition Errors']]"

    def __init__(self, driver):
        super(DefinitionErrorsPage, self).__init__(driver)
        self._view_panel = DefinitionErrorsPageViewPanel(driver)
        self.common_actions = {
            'load_commissioning_file_and_check_load_status':
                self._view_panel.load_commissioning_file_and_check_load_status,
            'validate_plan': self._view_panel.validate_plan,
            'activate_plan': self._view_panel.activate_plan,
        }
        self.__dict__.update(self.common_actions)
        self.driver = driver

    def get_definition_status(self):
        """
        Get definition status
        :return: str, definition status
        """
        self.open_definition_errors_tab()
        return self._view_panel.get_definition_status()

    def get_definition_errors(self, timeout=60):
        """
        Get definition errors
        :return: list, list contains dict
        """
        self.open_definition_errors_tab()
        return self._view_panel.get_definition_errors(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def open_definition_errors_tab(self):
        """
        Navigate to Definition Errors
        """
        tab = self.driver.find_element_by_xpath(self._DEFINITION_ERRORS_XPATH)
        tab.click()


class DefinitionErrorsPageViewPanel(ViewPanel):
    _VALIDATE_PLAN_RESULT_XPATH = '//table[@role="table"]'
    _DEFINITION_ERRORS_TABLE_XPATH = '//table[@role="table"]'
    _DEFINITION_ERRORS_TABLE_HEAD_XPATH = '//table[@role="table"]/thead/tr[1]/th'
    _DEFINITION_ERRORS_TABLE_ROW_XPATH = '//table[@role="table"]/tbody/tr'

    _EXPAND_VALIDATION_ERROR_XPATH = ('//button[@aria-label="collapse button" and'
                                      ' .//span[contains(@class, "mdi-format-list-bulleted")]]')

    def __init__(self, driver):
        super(DefinitionErrorsPageViewPanel, self).__init__(driver)
        common_action = ConfigurationCommonAction(driver)
        self.common_actions = {
            'load_commissioning_file_and_check_load_status':
                common_action.load_commissioning_file_and_check_load_status,
            'validate_plan': common_action.validate_plan,
            'activate_plan': common_action.activate_plan,
        }
        self.__dict__.update(self.common_actions)

    def get_definition_status(self):
        """
        Get definition status
        :return: str, definition status
        """
        self._expand_validation_error()
        return self.get_text_by_xpath(self._VALIDATE_PLAN_RESULT_XPATH)

    def _definition_errors(self):
        headers = [item.text.strip()
                   for item in self.driver.find_elements_by_xpath(self._DEFINITION_ERRORS_TABLE_HEAD_XPATH)]

        all_error_info = []
        for inex, tr_elem in enumerate(self.driver.find_elements_by_xpath(self._DEFINITION_ERRORS_TABLE_ROW_XPATH)):
            tds_elem = tr_elem.find_elements_by_xpath('td')
            td_value_list = []
            for td_elem in tds_elem:
                colspan = td_elem.get_attribute('colspan')
                colspan = int(colspan) if colspan else 1
                td_value = td_elem.text.strip()
                if "No data available" in td_value:
                    continue
                td_value_list.extend([td_value] * colspan)
            if td_value_list:
                all_error_info.append(dict(zip(headers, td_value_list)))
        return all_error_info

    def get_definition_errors(self, timeout=60):
        self._expand_validation_error()
        definition_errors = []
        try:
            self.wait_for_enable((By.XPATH, self._DEFINITION_ERRORS_TABLE_XPATH), timeout)
            definition_errors = self._definition_errors()
        except TimeoutException:
            pass
        finally:
            return definition_errors

    def _expand_validation_error(self):
        if self.element_exists(self._EXPAND_VALIDATION_ERROR_XPATH):
            self.click_element_by_xpath(self._EXPAND_VALIDATION_ERROR_XPATH)
